       cli.io.write(cli._style.dim(cli._redactRendered(delta)));
       _deltaStreamed = true;
       return;
@@ -266,9 +269,19 @@ extension AgentCliBusyPhase on AgentCli {
 /// evictions went to hide, or the model returned blank — issue #578)
