  /// (gh-1433 E4): the next compaction-facing line closes the stream
  /// line first, so the report never glues onto the live summary.
  bool _deltaStreamed = false;

  /// Closes the E4 live-summary stream line (one newline on the primary
  /// channel) before the next compaction-facing output lands.
  void _closeDeltaStreamLine() {
    if (!_deltaStreamed) return;
    _deltaStreamed = false;
    cli.io.write('\n');
  }

  @override
  void onDelta(String delta) {
    // gh-1636: the summary being written is internal checkpoint text —
    // echoing every delta onto the headless log buries the actual reply
    // the same way the full report block did. Hidden by default; the
    // gh-1430 E3 tier-2 `… reasoning Ns` line (armed around the whole
    // compaction window) keeps the wait visible without the dump.
    // `tui.showCompactionDetails` restores the gh-1433 E4 live stream.
    if (cli._logIsUi) {
      if (!cli.config.showCompactionDetails) return;
      cli.io.write(cli._style.dim(cli._redactRendered(delta)));
      _deltaStreamed = true;
      return;
    }
    // Live tail of the summary being written, shown in the busy row so
    // compaction reads as work, not a hang. Throttled — deltas are hot.
    final merged = (_compactionTail + delta).replaceAll('\n', ' ');
    _compactionTail = _rollingTail(merged);
    final now = DateTime.now();
    final last = _lastDeltaPhase;
    if (last != null &&
        now.difference(last) < const Duration(milliseconds: 150)) {
      return;
    }
    _lastDeltaPhase = now;
    cli._pushBusyPhase('Compacting context… $_compactionTail');
  }

  @override
  void onAttemptStart(String label, int attempt, Duration budget) {
    _closeDeltaStreamLine();
    // A slow/dead summarizer endpoint must read as a bounded wait, not a
    // silent hang: name the endpoint being tried and its time cap.
    cli._tuiController?.setBusyPhase(
      'Compacting context… $label (attempt $attempt, '
      '${budget.inSeconds}s cap)',
    );
    _compactionTail = '';

  // in YamlScalar) — accept both, like the `_scalarKeys` branch above.
  final scalar = value is YamlScalar ? value.value : value;
  if (scalar is bool || scalar == 'notify' || scalar == null) return;
  throw ConfigException(
    '"auto_update" must be true, false, or "notify", got: $scalar',
  );
}

void _validateTuiSection(Object? node, String label) {
  if (node is! YamlMap) {
    throw ConfigException('$label: tui section must be a map');
  }
  final unknown = [
    for (final key in node.keys)
      if (!{'theme', 'classic', 'showCompactionDetails'}.contains('$key'))
        '$key',
  ];
  if (unknown.isNotEmpty) {
    throw ConfigException(
      '$label: unknown tui key(s): ${unknown.join(', ')} '
      '(known: theme, classic, showCompactionDetails)',
    );
  }
  final theme = node['theme'];
  if (theme != null && '$theme'.trim().isEmpty) {
    throw ConfigException('$label: tui.theme must be a non-empty theme name');
  }
  for (final flag in const ['classic', 'showCompactionDetails']) {
    final value = node[flag];
    if (value != null && value is! bool) {
      throw ConfigException('$label: tui.$flag must be a boolean');
    }
  }
}

